candidates.raw:
    if ((wheels == NULL) || (field == NULL) || (command == NULL) || 
        (momentum == NULL) || (torque == NULL) || (energy == NULL) || 
        (dissipation == NULL)) {
        return ADCS_E_NULL;
    }

    if ((count < 1) || (count > 16) || (!adcs_is_finite_vec3(field))) {
        return ADCS_E_RANGE;
    }

    *momentum = (adcs_vec3_t){0.0, 0.0, 0.0};
    command->command = (adcs_vec3_t){0.0, 0.0, 0.0};
    command->saturated_axes = 0U;
    *torque = (adcs_vec3_t){0.0, 0.0, 0.0};
    *energy = 0.0;
    *dissipation = 0.0;

    adcs_status_t st = adcs_wheel_momentum(wheels, count, momentum);
    if (st != ADCS_OK) {
        return st;
    }

    st = adcs_momentum_unload_dipole(momentum, field, gain, dipole_limit, command, torque);
    if (st != ADCS_OK) {
        return st;
    }

    double total_energy = 0.0;
    for (size_t i = 0; i < count; ++i) {
        double j = wheels[i].inertia_kg_m2;
        double w = wheels[i].speed_rad_s;
        if (!isfinite(j) || !isfinite(w)) {
            return ADCS_E_RANGE;
        }
        total_energy += 0.5 * j * w * w;
    }
    *energy = total_energy;

    *dissipation = adcs_vec3_dot(momentum, torque);

    return ADCS_OK;
}

